#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, c, f, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) : y(y), c(c), f(f), cost(cost) {}
};

vector<Edge> graph_edges;
const int MAXNODES = 14043;
vector<int> adj_list[MAXNODES];

long long total_cost = 0;
long long dist_arr[MAXNODES];
int parent_node[MAXNODES], parent_edge_idx[MAXNODES], in_queue[MAXNODES];

const long long INF_VAL = 1e18;
int s_node = MAXNODES - 2;
int t_node = MAXNODES - 1;

int residual(int idx) {
    return graph_edges[idx].c - graph_edges[idx].f;
}

void find_path() {
    for (int i = 0; i < MAXNODES; i++) {
        dist_arr[i] = INF_VAL;
        parent_node[i] = -1;
        parent_edge_idx[i] = -1;
        in_queue[i] = 0;
    }
    dist_arr[s_node] = 0;
    queue<int> q;
    q.push(s_node);
    in_queue[s_node] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = 0;
        for (auto e_idx : adj_list[u]) {
            if (residual(e_idx) == 0) continue;
            int cst = graph_edges[e_idx].cost;
            int v = graph_edges[e_idx].y;
            if (dist_arr[v] > dist_arr[u] + cst) {
                dist_arr[v] = dist_arr[u] + cst;
                parent_node[v] = u;
                parent_edge_idx[v] = e_idx;
                if (in_queue[v] == 0) {
                    in_queue[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    int cur = t_node;
    while (cur != s_node) {
        graph_edges[parent_edge_idx[cur]].f++;
        graph_edges[parent_edge_idx[cur] ^ 1].f--;
        cur = parent_node[cur];
    }
    total_cost += dist_arr[t_node];
}

void connect_nodes(int from, int to, int cap, int cst) {
    adj_list[from].push_back(graph_edges.size());
    graph_edges.emplace_back(to, cap, 0, cst);
    adj_list[to].push_back(graph_edges.size());
    graph_edges.emplace_back(from, 0, 0, -cst);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x;
        connect_nodes(s_node, x, 1, 0);
    }
    int tt = 101;
    for (int i = 0; i < tt; i++)
        connect_nodes(1 + i * n, t_node, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        for (int j = 0; j < tt - 1; j++) {
            connect_nodes(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            connect_nodes(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
        }
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < tt - 1; j++)
            connect_nodes(i + j * n, i + j * n + n, k, 0);
    for (int i = 0; i < k; i++)
        find_path();
    cout << total_cost << endl;
}
